const canvas=document.getElementById("pong"),ctx=canvas.getContext("2d"),ball={x:canvas.width/2,y:canvas.height/2,radius:10,speedX:4,speedY:4},paddleWidth=10,paddleHeight=80,leftPaddle={x:0,y:canvas.height/2-paddleHeight/2,speed:0},rightPaddle={x:canvas.width-paddleWidth,y:canvas.height/2-paddleHeight/2,speed:4};let leftScore=0,rightScore=0;document.addEventListener("keydown",e=>{e.key==="ArrowUp"&&(leftPaddle.speed=-6),e.key==="ArrowDown"&&(leftPaddle.speed=6)}),document.addEventListener("keyup",e=>{(e.key==="ArrowUp"||e.key==="ArrowDown")&&(leftPaddle.speed=0)});function drawRect(e,t,n,s,o){ctx.fillStyle=o,ctx.fillRect(e,t,n,s)}function drawCircle(e,t,n,s){ctx.fillStyle=s,ctx.beginPath(),ctx.arc(e,t,n,0,Math.PI*2,!1),ctx.closePath(),ctx.fill()}function drawText(e,t,n,s,o="30px"){ctx.fillStyle=s,ctx.font=`${o} monospace`,ctx.fillText(e,t,n)}function resetBall(){ball.x=canvas.width/2,ball.y=canvas.height/2,ball.speedX=-ball.speedX,ball.speedY=4}function update(){leftPaddle.y+=leftPaddle.speed,leftPaddle.y=Math.max(Math.min(leftPaddle.y,canvas.height-paddleHeight),0),ball.x+=ball.speedX,ball.y+=ball.speedY,(ball.y-ball.radius<0||ball.y+ball.radius>canvas.height)&&(ball.speedY=-ball.speedY),ball.x-ball.radius<leftPaddle.x+paddleWidth&&ball.y>leftPaddle.y&&ball.y<leftPaddle.y+paddleHeight&&(ball.speedX=-ball.speedX),ball.x+ball.radius>rightPaddle.x&&ball.y>rightPaddle.y&&ball.y<rightPaddle.y+paddleHeight&&(ball.speedX=-ball.speedX),rightPaddle.y+paddleHeight/2<ball.y?rightPaddle.y+=rightPaddle.speed:rightPaddle.y-=rightPaddle.speed,rightPaddle.y=Math.max(Math.min(rightPaddle.y,canvas.height-paddleHeight),0),ball.x-ball.radius<0&&(rightScore++,resetBall()),ball.x+ball.radius>canvas.width&&(leftScore++,resetBall())}function draw(){drawRect(0,0,canvas.width,canvas.height,"black"),drawRect(leftPaddle.x,leftPaddle.y,paddleWidth,paddleHeight,"white"),drawRect(rightPaddle.x,rightPaddle.y,paddleWidth,paddleHeight,"white"),drawCircle(ball.x,ball.y,ball.radius,"white"),drawText(leftScore,canvas.width/4,50,"white"),drawText(rightScore,3*canvas.width/4,50,"white")}function gameLoop(){update(),draw(),requestAnimationFrame(gameLoop)}gameLoop()